import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    leading_rows = []
    for record in reader:
        if record:
            columns = record
            break
        leading_rows.append(record)
    else:
        return {"columns": [], "rows": leading_rows}

    rows = leading_rows
    width = max(2, len(columns))
    for record in reader:
        rows.append(record)
        width = max(width, len(record))

    # Give overflow fields their own columns so no field values are lost.
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for record in rows:
        record.extend([""] * (width - len(record)))

    return {"columns": columns, "rows": rows}
